import os, re

root = "/bench/repo"
# Match store.Memo as a type identifier, not MemoRelation/MemoShare/etc.
pat_store = re.compile(r'store\.Memo(?![A-Za-z0-9_])')
# Within package store, type Memo
pat_local = re.compile(r'\bMemo(?![A-Za-z0-9_])')

files_hit = []
for dirpath, dirnames, filenames in os.walk(root):
    # skip .git
    dirnames[:] = [d for d in dirnames if d != '.git' and d != 'node_modules' and d != 'dist']
    for fn in filenames:
        if not fn.endswith('.go'):
            continue
        path = os.path.join(dirpath, fn)
        rel = path[len(root)+1:]
        try:
            text = open(path, encoding='utf-8', errors='replace').read()
        except Exception:
            continue
        if 'package store' in text.split('\n')[0:5] or '/store/' in rel and 'package store' in text[:200]:
            # check if it's actually package store
            pkg = None
            for line in text.splitlines()[:20]:
                if line.startswith('package '):
                    pkg = line.split()[1]
                    break
            if pkg == 'store':
                # look for Memo type usage besides definition of other types like MemoRelation
                # Count hits of \bMemo\b that's not MemoX
                hits = []
                for i, line in enumerate(text.splitlines(), 1):
                    if pat_local.search(line) and not re.search(r'\bMemo(Relation|Share|Payload|Filter|Builder)', line):
                        # still might be FindMemo, UpdateMemo, DeleteMemo, CreateMemo, ListMemos, GetMemo
                        # For package store, we want type Memo specifically
                        if re.search(r'(?:^|[^\w])Memo(?:[^A-Za-z0-9_]|$)', line) and not re.search(r'(FindMemo|UpdateMemo|DeleteMemo|CreateMemo|ListMemos|GetMemo|ListMemo|DeleteMemos)', line.replace('*Memo', 'X').replace('[]*Memo','Y').replace('*Memo ','Z ')):
                            pass
                        if re.search(r'(?:\*Memo\b|\[\]\*Memo\b|&Memo\{|type Memo struct|\bMemo\b)', line):
                            # filter function names
                            if re.search(r'\b(CreateMemo|ListMemos|GetMemo|UpdateMemo|DeleteMemo|FindMemo)\b', line) and '*Memo' not in line and '[]*Memo' not in line and 'type Memo' not in line:
                                continue
                            hits.append((i, line.strip()[:120]))
                if hits:
                    files_hit.append((rel, 'store-pkg', len(hits)))
                continue
        if pat_store.search(text):
            files_hit.append((rel, 'store.Memo', len(pat_store.findall(text))))

for rel, kind, n in sorted(files_hit):
    print(f"{n:3} {kind:12} {rel}")
print("--- total files", len(files_hit))
